)

// Currency is an ISO 4217 currency code.
type Currency string

// The currencies Tally bills in.
const (
	USD Currency = "USD"
	EUR Currency = "EUR"
	GBP Currency = "GBP"
	JPY Currency = "JPY"
	KWD Currency = "KWD"
)

// currencies holds what Tally knows about each currency: how people write it and how many decimals its major unit has.
var currencies = map[Currency]struct {
	symbol   string
	decimals int
}{
	USD: {"$", 2},
	EUR: {"€", 2},
	GBP: {"£", 2},
	JPY: {"¥", 0},
	KWD: {"KWD ", 3},
}

// Valid reports whether c is a currency Tally bills in.
func (c Currency) Valid() bool {
	_, ok := currencies[c]
	return ok
}

// MinorUnits returns the number of decimals in c's major unit: 2 for dollars (1 dollar is 100 cents), 0 for yen and 3 for
// dinars (1 dinar is 1000 fils). A currency Tally does not bill in has 2.
func (c Currency) MinorUnits() int {
	if cur, ok := currencies[c]; ok {
		return cur.decimals
	}
	return 2
}

// ErrInvalidAmount is returned for an amount that cannot be read.
var ErrInvalidAmount = errors.New("invalid amount")

// ParseMajor reads an amount a person typed in major units ("12.50", "7", "1.250") and returns it in minor units. The
// number has at most the currency's decimals and may have fewer ("12.5" USD is 1250, "7" KWD is 7000); a JPY amount has no
// decimal point at all.
func ParseMajor(s string, c Currency) (int64, error) {
	if !c.Valid() {
		return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
	}
	s = strings.TrimSpace(s)
	d := c.MinorUnits()
	whole, frac, hasDot := strings.Cut(s, ".")
	if whole == "" || (hasDot && (d == 0 || frac == "")) {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	if len(frac) > d {
		return 0, fmt.Errorf("%w: %q has more than %d decimals for %s", ErrInvalidAmount, s, d, c)
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
		}
	}
	for len(frac) < d {
		frac += "0"
	}
	n, err := strconv.ParseInt(whole+frac, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	return n, nil
}

// Format renders an amount for people, with the currency's decimals: "$1,234.50", "€0.99", "¥1,000", "KWD 1.250", "-$5.00".
func Format(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	s := currencies[c].symbol + group(whole)
	if frac != "" {
		s += "." + frac
	}
	return sign + s
}

// FormatMajor renders an amount in major units for a person to type or read back with ParseMajor: "12.50", "1000", "1.250",
// "-0.005". It has the currency's decimals and no thousands separator.
func FormatMajor(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	s := strconv.FormatInt(whole, 10)
	if frac != "" {
		s += "." + frac
	}
	return sign + s
}

// split breaks an amount into its sign ("-" or ""), its whole major units and its fraction digits, which are zero-padded to
// the currency's decimals ("" for a currency without decimals).
func split(amount int64, c Currency) (sign string, whole int64, frac string) {
	if amount < 0 {
		sign, amount = "-", -amount
	}
	d := c.MinorUnits()
	pow := int64(1)
	for i := 0; i < d; i++ {
		pow *= 10
	}
	whole, rest := amount/pow, amount%pow
	if d > 0 {
		frac = fmt.Sprintf("%0*d", d, rest)
	}
	return sign, whole, frac
}

// group writes n with a comma between each group of three digits.
func group(n int64) string {
	s := strconv.FormatInt(n, 10)
	var b strings.Builder
	for i, r := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	return b.String()
}

// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }

// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }

// divRound divides and rounds half away from zero.
func divRound(num, den int64) int64 {
	if (num < 0) != (den < 0) {
		return -((abs(num) + abs(den)/2) / abs(den))
	}
	return (abs(num) + abs(den)/2) / abs(den)
}

func abs(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}
